\label{thm:intro-uniformity}
Let $s\geqslant1$ be an integer and $\varepsilon>0$. Uniformly for $X\geqslant3$ and
$$
X^{3/5+\varepsilon}\leqslant H\leqslant X,
$$
one has\footnote{See Section~\ref{subsec:notation} for the definition of the Gowers norm}
\begin{equation}\label{eq:intro-gowers-theorem}
\left\lVert \Lambda-\Lambda_X^\sharp\right\rVert_{U^s(X,X+H]}=o_{s,\varepsilon}(1).
\end{equation}

\label{thm:discorrelation}
Let $d,D \in \mathbb{N}$, let $\varepsilon>0$, $\delta\in(0,1/2)$, $X\geqslant 3$, and
\begin{equation*}
  X^{3/5+\varepsilon}\leqslant H\leqslant X^{1-\varepsilon}.
\end{equation*}
Let $G/\Gamma$ be a filtered nilmanifold\footnote{The symbols relating to nilsequences have the same meanings as in \cite[Section~2.3]{MSTT}.} of degree at most $d$, dimension at most $D$, and complexity at most $1/\delta$, and let $F\colon G/\Gamma\to\mathbb C$ be a Lipschitz function of norm at most $1/\delta$. Then, for every $A>0$,
\begin{align}
  \sup_{g\in\operatorname{Poly}(\mathbb Z\to G)} \left\lvert\sum_{X<n\leqslant X+H}\mu(n)\overline{F(g(n)\Gamma)}\right\rvert^{\,*} &\ll_{A,\varepsilon,d,D} \delta^{-O_{d,D}(1)}\frac{H}{\log^A X},\label{eq:mobius-discor}\\
  \sup_{g\in\operatorname{Poly}(\mathbb Z\to G)} \left\lvert\sum_{X<n\leqslant X+H}(\Lambda(n)-\Lambda_X^\sharp(n))\overline{F(g(n)\Gamma)}\right\rvert^{\,*} &\ll_{A,\varepsilon,d,D} \delta^{-O_{d,D}(1)}\frac{H}{\log^A X}.\label{eq:lambda-discor}
\end{align}

\label{cor:polynomial-phases}
Let $\varepsilon>0$, $d\geqslant 1$, $A>0$, $X\geqslant 3$, and $X^{3/5+\varepsilon}\leqslant H\leqslant X^{1-\varepsilon}$. For every polynomial $P\in\mathbb R[Y]$ of degree at most $d$,
\begin{equation}\label{eq:mu-poly}
  \left\lvert\sum_{X<n\leqslant X+H}\mu(n)e(P(n))\right\rvert \ll_{A,d,\varepsilon} \frac{H}{\log^A X}.
\end{equation}
Moreover, we have
\begin{equation}\label{eq:lambda-poly}
  \left\lvert\sum_{X<n\leqslant X+H}\Lambda(n)e(P(n))\right\rvert \ll_{A,d,\varepsilon} \frac{H}{\log^A X},
\end{equation}
unless, writing
\begin{equation*}
  P(\lfloor X\rfloor +m)=\alpha_0+\alpha_1m+\cdots+\alpha_dm^d,
\end{equation*}
there exists an integer $1\leqslant q\leqslant \log^{O_{A,d,\varepsilon}(1)} X$ such that
\begin{equation}\label{eq:major-arc-poly}
  \max_{1\leqslant j\leqslant d} H^j\left\lVert q\alpha_j\right\rVert_{\mathbb R/\mathbb Z}
  \leqslant \log^{O_{A,d,\varepsilon}(1)}X.
\end{equation}

\label{thm:intro-mobius}
Let $\varepsilon>0$. Uniformly for $X\geqslant3$ and
$$
  X^{19/35+\varepsilon}\leqslant H\leqslant X,
$$
one has
\begin{equation}\label{eq:intro-mobius-theorem}
  \left|\sum_{X<n\leqslant X+H}\mu(n)\right|\ll_{\varepsilon} \frac{H}{\log^{1/3-\varepsilon} X}.
\end{equation}

\label{thm1.4}
Let $\varepsilon > 0$ and let $k\geqslant 5$ be an integer. Uniformly for $X\geqslant 3$ and $X^{19/35+\varepsilon}\leqslant H\leqslant X$ one has
$$\sum_{X<n\leqslant X+H}d_{k}(n)=(X+H)P_{k-1}(\log(X+H))-XP_{k-1}(\log X)+O\big(H(\log X)^{(2/3+\varepsilon)k-1}\big),$$ where $P_{k-1}$ is an explicit polynomial of degree $k-1$ (see \cite[equation (5.36) in Section II.5.4]{Tenenbaum2015})\footnote{In~\cite[Theorem 1.3]{MatomakiTeravainenMobius} the main term is simplified to $HQ_{k-1}(\log X)$ where $Q_{k-1}=P_{k-1}+P_{k-1}'$ in the current paper's notation, but in fact this is only valid if $H/X\ll(\log X)^{1-k/3+k\varepsilon}$, and for $H$ close to $X$ one must retain the difference above.}.

\label{thm1.5}
Let $\varepsilon>0$. Uniformly for $X\geqslant 100$ and $X^{19/35+\varepsilon}\leqslant H\leqslant X$ one has
$$   \sum_{\substack{X<n\leqslant X+H \\ n\in E_{2}}}1=\frac{H\log\log X}{\log X}+O\Big(\frac{H\log\log\log X}{\log X}\Big). $$

Let $\nu\geqslant 0$ and $T \geqslant 1$, and let $\mathcal{T} \subseteq [T, 2T]$ be a subset. Suppose that $A(s)$ is a Dirichlet polynomial whose coefficients are supported on $(X^\beta, 2X^{\beta}]$ with $\beta > 0$. We define $\mathcal{N}_A(\nu;\mathcal{T})$ to be the maximal cardinality of a $1$-separated subset $\mathcal{U}\subseteq\mathcal{T}$ such that
\begin{equation*}
  |A(1/2+it)|\geqslant X^{\beta(\frac{1}{2}-\nu)}\qquad\text{for all }t\in\mathcal{U}.
\end{equation*}

\label{le:MVHuGM}
Let $B \geqslant 1$ be fixed. Let $\beta>0$, $X\geqslant3$, and
\begin{equation*}
  A(s)=\sum_{X^\beta<n\leqslant 2X^\beta}a(n) n^{-s},\qquad |a(n)|\leqslant d_B(n)\log^B X.
\end{equation*}
Let $T = X^\tau$ with $\tau \in (0, 1]$.
Then the following statements hold:

\begin{enumerate}[label=(\roman*)]
  \item For every $\nu \geqslant 0$ and every fixed $k \in \mathbb{N}$, we have
\begin{equation}\label{eq:hm-large-values-bound}
  \mathcal N_A(\nu ; [T, 2T])\ll X^{\mathcal{K}(\beta k,\nu;\tau)+o(1)}.
\end{equation}

  \item There is a constant $C = C(B) > 0$ such that the following holds. Let 
  \[
  a(n) = \mathbf{1}_{n \in I} \chi(n) \log^r n,
  \]
   where $I \subseteq (X^\beta, 2X^\beta]$ is an interval, $\chi$ is a Dirichlet character of modulus $\ll \log^B X$ and $r \in \{0, 1\}$. Let $\mathcal{T} \subseteq [T, 2T]$ be such that
  \begin{equation} \label{eq:4thmomcond}
|A(1/2+it)| \geqslant \frac{X^{\beta/2}}{T} \log^C X
\end{equation}
for every $t \in \mathcal{T}$. Then, if $\tau>1/\sqrt{\log X}$, for every $\nu \geqslant 0$ we have
  \begin{equation} \label{eq:fourthMomentN}
    \mathcal{N}_A(\nu; \mathcal{T}) \ll X^{\tau + 2\beta(2\nu-1) +o(1)}.
  \end{equation}
\end{enumerate}

\label{lem:sparse-mean-square}
Let $N, T \geqslant 2$ and
$$
  A(s)=\sum_{N<n\leqslant2N}a(n)n^{-s}
$$
with $a(n) \in \mathbb{C}$. Let $\mathcal{U}\subset[-T,T]$ be $1$-separated. Then, for $\eta \in (0, 1/2]$,
\begin{equation*}
  \sum_{t\in\mathcal{U}}|A(it)|^2
  \ll_\eta
  \left(N+|\mathcal{U}| \cdot T^{\frac{9}{2} \cdot \eta^{3/2}} N^{1-\eta}\log^{2/3} T\right) \sum_{N < n \leqslant 2N} |a(n)|^2.
\end{equation*}

\label{le:inversecost}
 Let $\tau>0$, $\varepsilon_0 >0$, $J\in \mathbb N$ and $I \subseteq \mathbb{R}_{\geqslant 0}$. For each $j \in \{1, \dotsc, J\}$, let $\beta_j \geqslant 0$, let $H_j \colon I \to [0, \tau],$ and define
  \[
    P_j(t) = \inf\{\beta_j y \colon y \in I, H_j(y) \geqslant t\}.
  \]
  Assume that
  \begin{equation} \label{eq:SumPjbound}
    \sum_{j = 1}^J P_j(t) > t+\varepsilon_0 \qquad \text{ for all } t\in[0,\tau].
  \end{equation}
  Then, for arbitrary $y_1, \dotsc, y_J \in I$ one has
  \begin{equation} \label{eq:minHjbound}
    \min_{j \in \{1, \dotsc, J\}} H_j(y_j) < \sum_{j = 1}^J \beta_j y_j -\varepsilon_0.
  \end{equation}

\label{le:16/35comput}
Let $\varepsilon \in (0, 1/100), \, \tau_1=\frac{16}{35}-\varepsilon$ and $ \tau \in [\varepsilon, \tau_1]$. Let $\beta_1, \beta_2, \beta_3 \in [\varepsilon, \tau_1]$ with $\beta_1+\beta_2+\beta_3=1$. For $\nu \geqslant 0$, define
  \begin{align*}
    H_{1,\tau}(\nu) &:= \max\left\{0,\min\{\tau + 2\beta_1(2\nu-1), \mathcal{K}(2\beta_1, \nu; \tau)\}\right\} \\
    H_{2,\tau}(\nu) &:= \min\{\mathcal{K}(\beta_2, \nu; \tau), \mathcal{K}(2\beta_2, \nu; \tau)\} \\
    H_{3,\tau}(\nu) &:= \min\{\mathcal{K}(\beta_3, \nu; \tau), \mathcal{K}(2\beta_3, \nu; \tau)\}.
  \end{align*}
For $j \in \{1, 2, 3\}$, define the function $P_{j,\tau} \colon [0, \tau] \to \mathbb{R}_{\geqslant 0}$ via
  \[
    P_{j,\tau}(t) = \inf\{\beta_j \nu \colon \nu \in [\varepsilon^6, \varepsilon^{-1}], H_{j,\tau}(\nu) \geqslant t\}.
  \]

Then, for every $t \in [0, \tau]$, we have
 \begin{equation} \label{eq:HBICompPjClaim}
   P_{1,\tau}(t)+P_{2,\tau}(t)+P_{3,\tau}(t) > t+\varepsilon^{10}.
 \end{equation}

\label{lem:BHP-trilinear-estimates}
Let $\varepsilon > 0$ and $B \geqslant 1$. Let
\[
  1\leqslant T_1\leqslant X^{2/5-\varepsilon}
\]
and $\mathcal{T} \subseteq [-T_1, T_1]$.
Let $\beta_1, \beta_2, \beta_3 \in [\varepsilon, 1/2]$ be such that $\beta_2 \leqslant \beta_3 \leqslant \beta_1$ and $\beta_1 + \beta_2 + \beta_3 = 1$. For $j \in \{1, 2, 3\}$, let
\begin{align} \label{eq:upper-saving-5.1}
  A_j(s)=\sum_{X^{\beta_j} <n\leqslant2X^{\beta_j}} a_{j}(n) n^{-s},
\end{align}
where
\[
  |a_j(n)|\ll_B d_B(n)\log^B X
\]
and
\begin{equation} \label{eq:BHPsup}
  \sup_{|t|\leqslant T_1}|A_2(1/2+it)|
  \ll_A \frac{X^{\beta_2/2}}{\log^A X}
\end{equation}
for every $A \geqslant 1.$

Then
\begin{equation}\label{eq:bhp-trilinear-integral}
  \int_{\mathcal{T}} |A_1(1/2+it)A_2(1/2+it)A_3(1/2+it)|\,\textnormal{d} t \ll_{A, B}\frac{X^{1/2}}{\log^A X}
\end{equation}
for every $A \geqslant 1.$

\label{le:2/5comput}
  Let $\varepsilon, \varepsilon_0 > 0$, $\tau \in [\varepsilon, \frac{2}{5}-\varepsilon]$, and, for $\beta \geqslant \varepsilon$, define the function $H_{\beta, \tau} \colon \mathbb{R}_{\geqslant 0} \to [0, \tau]$ via
  \begin{align} \label{eq:Hbetatau5.2}
    H_{\beta, \tau}(\nu) &:= \min_{k \in \{1, 2\}} \mathcal{K}(k\beta, \nu; \tau)
  \end{align}
  and the function $P_{\beta, \tau} \colon [0, \tau] \to \mathbb{R}_{\geqslant 0}$ via
  \[
    P_{\beta, \tau}(t) = \inf\{\beta \nu \colon \nu \in [\varepsilon^6, \varepsilon^{-1}], H_{\beta, \tau}(\nu) \geqslant t\}.
  \]

Then, for every $\beta_1 \in [2/5, 1/2]$ and $\beta_2, \beta_3 \in [1/5,1/3]$ with $\beta_1+\beta_2+\beta_3=1$ and every $t \in [0, \tau]$, we have
 \begin{equation} \label{eq:BHPCompPjClaim}
   P_{\beta_1, \tau}(t)+P_{\beta_2, \tau}(t)+P_{\beta_3, \tau}(t) > t+\varepsilon^{10}.
 \end{equation}

By the Cauchy--Schwarz inequality, the mean value theorem for Dirichlet polynomials (see e.g.~\cite[Theorem 9.1]{IwaniecKowalski}), and the pointwise hypothesis~\eqref{eq:BHPsup},
\begin{align*}
& \int_{\mathcal T\cap[-2X^\varepsilon,2X^\varepsilon]}
 |A_1(1/2+it)A_2(1/2+it)A_3(1/2+it)|\,\,\textnormal{d} t \\
 &\leqslant \sup_{|t|\leqslant T_1}|A_2(1/2+it)|
 \left(\int_{-2X^\varepsilon}^{2X^\varepsilon}|A_1(1/2+it)|^2\,\,\textnormal{d} t\right)^{1/2}
   \left(\int_{-2X^\varepsilon}^{2X^\varepsilon}|A_3(1/2+it)|^2\,\,\textnormal{d} t\right)^{1/2} \\
  &\ll_{A,B}\frac{X^{1/2}}{\log^A X}
\end{align*}
for any $A \geqslant 1$.
By dyadic splitting and symmetry (using complex conjugates of coefficients), it is enough to prove~\eqref{eq:bhp-trilinear-integral} with $\mathcal{T}$ replaced by
\[
 \mathcal T_T=\mathcal T\cap[T,2T],\qquad [T,2T]\subseteq[X^\varepsilon,T_1].
\]

Suppose first that $\beta_1-\beta_3\leqslant1/5$. The Dirichlet polynomial Baker--Harman--Pintz parallelogram estimate in \cite[Lemma~7.3]{HarmanBook}, in the form used in the proof of \cite[Lemma~3.5(i)]{MSTT}, applies with $\theta=3/5$, since
\[
 |\beta_1-\beta_3|\leqslant\frac15=2\theta-1,
 \qquad 1-\beta_1-\beta_3=\beta_2\leqslant\frac13<\frac25=4\theta-2,
\]
and its pointwise hypothesis for the factor corresponding to $\beta_2$ is precisely~\eqref{eq:BHPsup}. This gives
\[
 \int_{\mathcal T_T}|A_1(1/2+it)A_2(1/2+it)A_3(1/2+it)|\,\,\textnormal{d} t
 \ll_{A,B}\frac{X^{1/2}}{\log^A X}.
\]

It remains to consider $\beta_1-\beta_3>1/5$. Since $\beta_3=1-\beta_1-\beta_2$, the ordering of the $\beta_j$ shows that the closure of this region is the triangular region with $(\beta_1,\beta_2,\beta_3)\in\mathfrak T_\triangle$, where
\begin{equation}\label{eq:triangle-region-set}
  \mathfrak T_{\triangle}\coloneqq \operatorname{conv}\left\{
  \left(\frac7{15},\frac4{15},\frac4{15}\right),
  \left(\frac12,\frac14,\frac14\right),
  \left(\frac12,\frac15,\frac3{10}\right)
  \right\},
\end{equation}
where $\operatorname{conv}$ denotes the convex hull. In particular, this triangle is contained in the compact region
\begin{equation}\label{eq:blue-range}
  \beta_1\in\left[\frac25,\frac12\right],\qquad \beta_2,\beta_3\in\left[\frac15,\frac{3}{10}\right];
\end{equation}
see Figure~\ref{fig:typeII-region}.

