Write $T=X^{\tau}$ with $\tau\in[\varepsilon,2/5-\varepsilon]$. By Lemma~\ref{le:MVHuGM}, for any $\nu\geqslant0$ and $j\in\{1,2,3\}$,
\[
  \mathcal N_{A_j}(\nu;\mathcal T_T)
  \ll X^{\min_{k\in\{1,2\}}\mathcal K(k\beta_j,\nu;\tau)+o(1)}.
\]
Now Proposition~\ref{prop:one-var-check} and Lemma~\ref{le:2/5comput} give the required estimate on $\mathcal T_T$. Summing the dyadic blocks completes the proof.

\label{lem:gowers-gluing}
Let $s \in \mathbb{N}$. Let  $a \in \mathbb{R}$ and $H\geqslant 2L\geqslant 4$, and write $I=(a,a+H]$. Then, for every $f\colon\mathbb Z\to\mathbb C$,
\[
  \|f\|_{U^s(I)}\ll_s\max_{\substack{I'\subseteq I\text{ an interval}\\ L/2<|I'|\leqslant L}}
  \|f\|_{U^s(I')}.
\]

\label{prop:non-abelian}
Let $\varepsilon>0$ and $d,D,A\geqslant1$. Suppose that
\begin{equation*}
 2\leqslant X^{3/5+\varepsilon}\leqslant H\leqslant X^{1-\varepsilon}.
 \end{equation*}
Let $G/\Gamma$ be a filtered nilmanifold of degree at most $d$,
dimension at most $D$, and complexity at most $\log^A X$. Let $F\colon G/\Gamma\to\mathbb C$ have zero mean and satisfy
\begin{equation*}
 \|F\|_{\mathrm{Lip}}\leqslant\log^A X,
\end{equation*}
let $g:\mathbb Z\to G$ be polynomial, and let
\begin{equation*}
 f\in\{\Lambda-\Lambda_X^\sharp,\mu\}.
\end{equation*}
Then
\begin{equation}\label{eq:uniform-nonabelian-bound}
 \left|\sum_{X<n\leqslant X+H}f(n)F(g(n)\Gamma)\right|^*\ll_{d,D,A,\varepsilon}\frac{H}{\log^A X},
\end{equation}
unless the following exceptional alternative holds.

There exist $A_1=C(d,D,A,\varepsilon)>0$, an admissible trilinear component $h$
arising from Proposition~\ref{prop:HB-reduction}\textup{(c)} and a real number
\begin{equation*}
 |T|\leqslant (X/H)^{d+1}\log^{A_1} X
\end{equation*}
such that
\begin{align}
 \left|\sum_{X<n\leqslant X+H}f(n) n^{iT} \right|^*&\gg_{d,D,A,\varepsilon}H\log^{-A_1} X,
 \label{eq:original-mult-correlation}\\
 \left|\sum_{X<n\leqslant X+H}h(n)n^{iT}\right|^*&\gg_{d,D,A,\varepsilon}H\log^{-A_1} X.
 \label{eq:component-multiplicative-correlation}
\end{align}

\label{prop:ramare-component-comparison}
Let $\varepsilon>0$, $B_0>0$, and $X^{19/35+\varepsilon}\leqslant H\leqslant Y$. Let $S_{\mathcal I}$ be any dyadic component of the form \eqref{eq:dyadic-ramare-component}. Then
\begin{equation}\label{eq:ramare-component-comparison}
  S_{(X,X+H]}=\frac{H}{Y}S_{(X,X+Y]}+O_{\varepsilon,B_0}\left(\frac{H}{\log^{B_0} X}\right).
\end{equation}
The estimate is uniform in the dyadic parameters satisfying \eqref{eq:product-dyadic-lengths}.
